query GetRawContent($id: ID!) {
          product(id: $id) {
            id
            title
            handle
            status
            descriptionHtml
            priceRangeV2 {
              minVariantPrice { amount currencyCode }
              maxVariantPrice { amount currencyCode }
            }
            variants(first: 50) {
              edges {
                node {
                  id
                  selectedOptions { name value }
                  media(first: 5) { edges { node { ... on MediaImage { id } } } }
                }
              }
            }
            options {
              id
              name
              optionValues { id name }
            }
          }
        }
